update booking_order
set status = #{order.status},
    payment_no = #{order.paymentNo},
    paid_at = #{order.paidAt}
where id = #{order.id}
  and status = #{oldStatus}
  and expire_at > #{order.paidAt}

mapper.select:
select from booking_order bo join admission_session s on s.id = bo.session_id join venue v on v.id = s.venue_id where bo.user_id = #{userId}
and bo.status = #{status}
order by bo.created_at desc, bo.id desc

select 
from booking_order bo
join admission_session s on s.id = bo.session_id
join venue v on v.id = s.venue_id
where s.venue_id = #{venueId}

    and bo.status = #{query.status}


    and bo.order_no = #{query.orderNo}


    and bo.session_id = #{query.sessionId}


    and s.visit_date = #{query.visitDate}

order by bo.created_at desc, bo.id desc

select ,

from booking_order bo
join admission_session s on s.id = bo.session_id
join venue v on v.id = s.venue_id
where bo.id = #{orderId}
  and bo.user_id = #{userId}
